(6737838, 1008281, 147303, '<td valign="top">Very nice!  Except for the larger blurb of light under the red flower, my eye is drawn to the matching hues of light around each flour.  An improvement would''ve been really hiding the cords, but it''s a neat photo.</td>', 'Very nice!  Except for the larger blurb of light under the red flower, my eye is drawn to the matching hues of light around each flour.  An improvement would''ve been really hiding the cords, but it''s a neat photo.', '2012-04-10 11:22:38.000000', NULL, 1),
(6737839, 1007480, 147303, '<td valign="top">I really like this depth of field that was achieved, along with the split down the middle.  I find my eye drawn down toward the end.</td>', 'I really like this depth of field that was achieved, along with the split down the middle.  I find my eye drawn down toward the end.', '2012-04-10 11:23:29.000000', NULL, 1),
