(6737841, 1008141, 11769, '<td valign="top">Simply</td>', 'Simply', '2012-04-10 11:24:03.000000', NULL, 1),
(6737842, 1008087, 147303, '<td valign="top">Very nice!  This photo has great sharpness and clarity and the contrasting color of the doors against the wide walls is great.  I like staring at this photo.</td>', 'Very nice!  This photo has great sharpness and clarity and the contrasting color of the doors against the wide walls is great.  I like staring at this photo.', '2012-04-10 11:24:15.000000', NULL, 1),
