(6737861, 1008288, 61679, '<td valign="top">Back to comment and bump: Though my memory is blurry, I still cherish the time we spent, dancing the night away.</td>', 'Back to comment and bump: Though my memory is blurry, I still cherish the time we spent, dancing the night away.', '2012-04-10 11:33:36.000000', NULL, 1),
